import type { BankQuestion } from "@/lib/bank";

/** Business Economics & Strategy (Management & Commerce): 173 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-business-economics-1","question":"Other things remaining the same, a fall in the price of tea leads to:","options":["A rightward shift of the demand curve for tea","A leftward shift of the supply curve of tea","A movement up along the demand curve for tea","A movement down along the demand curve for tea"],"answer":3,"explanation":"A change in the good's own price changes quantity demanded, shown as a movement along the existing demand curve. Shifts come from income, prices of related goods, tastes and similar factors.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-2","question":"If consumers' incomes rise, the demand curve for a normal good:","options":["Shifts to the right","Shifts to the left","Does not move; quantity demanded rises along the curve","Becomes vertical"],"answer":0,"explanation":"For a normal good, higher income raises demand at every price, so the whole curve shifts right. For an inferior good it would shift left.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-3","question":"Demand is Qd = 100 − 2P and supply is Qs = 20 + 3P. What are the equilibrium price and quantity?","options":["P = ₹20, Q = 60","P = ₹16, Q = 68","P = ₹24, Q = 52","P = ₹16, Q = 84"],"answer":1,"explanation":"100 − 2P = 20 + 3P → 5P = 80 → P = 16; Q = 100 − 32 = 68 (check: 20 + 48 = 68). P = 20 comes from dropping the supply intercept.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-4","question":"When the price of a snack rises from ₹10 to ₹12, weekly sales fall from 100 to 80 packets. Using the midpoint (arc) method, what is the price elasticity of demand (absolute value)?","options":["1.00","1.50","1.22","0.82"],"answer":2,"explanation":"%ΔQ = 20/90 = 22.22%; %ΔP = 2/11 = 18.18%; elasticity = 22.22/18.18 = 1.22. Using the initial values gives 20%/20% = 1.00, and using the final values gives 25%/16.67% = 1.50, which is why the midpoint method is used.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-5","question":"A firm's price elasticity of demand is −0.4. If it raises its price by 10%, total revenue will change by approximately:","options":["+5.6%","+6.0%","−4.0%","+14.0%"],"answer":0,"explanation":"Quantity falls by 0.4 × 10% = 4%. New revenue = 1.10 × 0.96 = 1.056 of the old, i.e. +5.6%. +6% is the rough additive approximation (10 − 4) that ignores the cross term. With inelastic demand a price rise raises revenue.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-6","question":"Demand is Q = 200 − 4P. What is the point price elasticity of demand at P = 30?","options":["−0.67","−4.0","−1.5","−1.2"],"answer":2,"explanation":"At P = 30, Q = 80. Elasticity = (dQ/dP) × P/Q = −4 × 30/80 = −1.5. −0.67 inverts P/Q; −4 is just the slope.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-7","question":"With demand Q = 200 − 4P, at what price is total revenue maximised, and what is the elasticity there?","options":["₹50, elasticity −1","₹25, elasticity −1","₹25, elasticity −2","₹30, elasticity −1.5"],"answer":1,"explanation":"TR = P(200 − 4P) = 200P − 4P²; dTR/dP = 200 − 8P = 0 → P = 25, Q = 100. Elasticity = −4 × 25/100 = −1: revenue peaks where demand is unit-elastic. ₹50 is the choke price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-8","question":"When household incomes rise by 8%, demand for air travel rises by 12%. The good is:","options":["A necessity, with income elasticity 0.67","An inferior good, with income elasticity −1.5","A luxury, with income elasticity 0.67","A luxury, with income elasticity 1.5"],"answer":3,"explanation":"Income elasticity = 12%/8% = 1.5. Greater than 1 means demand grows faster than income: a luxury (a normal good). A necessity has 0 < e < 1; an inferior good has e < 0.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-9","question":"A 10% rise in the price of coffee raises the quantity of tea demanded by 5%. The cross-price elasticity and the relationship are:","options":["−0.5; complements","+2.0; substitutes","+0.5; substitutes","+0.5; complements"],"answer":2,"explanation":"Cross elasticity = %ΔQ(tea)/%ΔP(coffee) = 5/10 = +0.5. A positive value means the goods are substitutes; complements have negative cross elasticity.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-10","question":"Demand for a product is Q = 1,000/P² (constant elasticity). If price rises from ₹10 to ₹11, by how much does total revenue change?","options":["+10.00%","−10.00%","0.00%","−9.09%"],"answer":3,"explanation":"Constant elasticity −2. TR = P × 1,000/P² = 1,000/P, so TR falls from 100 to 1,000/11 = 90.91, a change of −9.09%. Revenue falls because demand is elastic; it would be unchanged only with unit elasticity.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-11","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. The government levies a tax of ₹5 per unit on sellers. How much of the tax is borne by consumers per unit?","options":["₹3","₹2","₹5","₹2.50"],"answer":0,"explanation":"Pre-tax: 120 − 2P = 3P − 30 → P = 30, Q = 60. With the tax, sellers receive P − 5: 120 − 2P = 3(P − 5) − 30 → P = 33, Q = 54. Buyers pay ₹3 more and sellers receive ₹28 (₹2 less). The less elastic side (here demand, slope 2 vs 3) bears more.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-12","question":"With demand Qd = 120 − 2P, supply Qs = 3P − 30 and a ₹5 per-unit tax that cuts the traded quantity from 60 to 54, what are the government's tax revenue and the deadweight loss?","options":["Revenue ₹300; deadweight loss ₹15","Revenue ₹270; deadweight loss ₹15","Revenue ₹270; deadweight loss ₹30","Revenue ₹300; deadweight loss ₹0"],"answer":1,"explanation":"Revenue = tax × new quantity = 5 × 54 = ₹270. Deadweight loss = ½ × tax × fall in quantity = ½ × 5 × 6 = ₹15. ₹300 uses the pre-tax quantity; ₹30 forgets the ½.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-13","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. If the government fixes a maximum price of ₹25, what results?","options":["A surplus of 25 units","A shortage of 10 units","A shortage of 25 units","No effect, because ₹25 is above equilibrium"],"answer":2,"explanation":"Equilibrium is P = 30. At ₹25, Qd = 70 and Qs = 45, so there is excess demand (shortage) of 25. A binding ceiling must be below equilibrium.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-14","question":"Demand is Qd = 200 − 5P and supply is Qs = 5P − 20. A minimum support price of ₹26 is announced. What is the resulting surplus?","options":["40 units","20 units","0 units, because the floor is below equilibrium","110 units"],"answer":0,"explanation":"Equilibrium: 200 − 5P = 5P − 20 → P = 22. At ₹26, Qd = 70 and Qs = 110, a surplus of 40. 110 is quantity supplied, not the surplus.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-15","question":"A Giffen good is one for which:","options":["Demand rises when income rises","Demand is perfectly elastic","Consumers buy more because a high price signals status","Quantity demanded rises when its price rises, because it is strongly inferior and a large part of the budget"],"answer":3,"explanation":"Giffen goods are inferior staples on which poor households spend much of their income; the income effect of a price rise outweighs the substitution effect. Status-driven demand (option four) describes Veblen goods.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-16","question":"Which factors make the demand for a product MORE price elastic? I. Many close substitutes. II. A large share of the consumer's budget. III. The product is habit-forming. IV. A longer time to adjust.","options":["I, II, III and IV","I, II and IV","I and III only","II, III and IV"],"answer":1,"explanation":"Substitutes, budget share and time all increase elasticity. Habit-forming goods (and necessities) have inelastic demand, so III works the other way.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-17","question":"Assertion (A): When demand is much less elastic than supply, most of a per-unit tax is borne by buyers. Reason (R): The side of the market that is less able to change quantity in response to price bears the larger share of a tax.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: tax incidence falls on the less elastic side. Share borne by buyers = Es/(Es + |Ed|).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-18","question":"When a firm raised its price from ₹50 to ₹55, its revenue rose from ₹10,000 to ₹10,450. What is the arc (midpoint) price elasticity of demand?","options":["−1.00 (unit elastic)","−0.54 (inelastic)","−1.86 (elastic)","+0.45 (Giffen good)"],"answer":1,"explanation":"Quantities: 10,000/50 = 200 and 10,450/55 = 190. %ΔQ = −10/195 = −5.13%; %ΔP = 5/52.5 = 9.52%. Elasticity = −0.54. Revenue rose with price, which already signals inelastic demand.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-19","question":"When the price of cotton yarn rises by 20%, quantity supplied rises by 30%. Supply is:","options":["Inelastic, with elasticity 0.67","Unit elastic","Elastic, with elasticity 0.67","Elastic, with elasticity 1.5"],"answer":3,"explanation":"Price elasticity of supply = 30%/20% = 1.5 > 1, so supply is elastic.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-20","question":"A market has 100 buyers each with demand q = 20 − 2P and 50 buyers each with demand q = 30 − 3P. What is the total quantity demanded at P = ₹4?","options":["1,200","3,500","2,100","30"],"answer":2,"explanation":"Market demand = 100(20 − 2P) + 50(30 − 3P) = 3,500 − 350P. At P = 4: 3,500 − 1,400 = 2,100. Individual demands are added horizontally (quantities at each price). 30 adds one buyer of each type.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-21","question":"A brand's price elasticity is −2 and its advertising elasticity is 0.25. If it cuts price by 5% and raises advertising spend by 20%, by roughly how much will unit sales change?","options":["+10%","+5%","+15%","−5%"],"answer":2,"explanation":"Price effect = −2 × (−5%) = +10%; advertising effect = 0.25 × 20% = +5%. Total ≈ +15%. Taking only one of the two effects gives +10% or +5%.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-22","question":"The income elasticity of demand for coarse grain is −0.3. If incomes rise by 10%, demand for coarse grain will:","options":["Fall by 3%","Rise by 3%","Fall by 30%","Rise by 0.3%"],"answer":0,"explanation":"%ΔQ = income elasticity × %ΔY = −0.3 × 10% = −3%. A negative income elasticity marks an inferior good.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-23","question":"Supply is Qs = 4P − 20. Which statement about its price elasticity is correct?","options":["Elasticity is 4 at every price because the slope is constant","Elasticity is 0.5 at P = 10 and rises with price","Elasticity is 1 at every price because the curve is a straight line","Elasticity is 2 at P = 10 and falls towards 1 as price rises"],"answer":3,"explanation":"Es = (dQ/dP) × P/Q = 4P/(4P − 20). At P = 10: 40/20 = 2. As P rises, the ratio approaches 1. A linear supply curve has constant elasticity of 1 only if it passes through the origin; one that cuts the price axis (as here) is elastic everywhere.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-24","question":"Which statements are correct for a per-unit tax on a good with perfectly inelastic demand? I. Buyers bear the entire tax. II. The quantity traded does not change. III. There is no deadweight loss.","options":["I and II only","I, II and III","I only","II and III only"],"answer":1,"explanation":"With vertical demand, quantity cannot fall, so the price rises by the full tax (I), quantity is unchanged (II) and no trades are lost, so there is no deadweight loss (III).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-25","question":"A retailer's price elasticity of demand is −2. If it cuts prices by 10%, what happens to total revenue?","options":["It rises by about 10%","It falls by about 8%","It rises by about 8%","It rises by about 20%"],"answer":2,"explanation":"Quantity rises 2 × 10% = 20%. Revenue = 0.90 × 1.20 = 1.08 → +8%. Demand is elastic, so a price cut raises revenue. +20% is the quantity change, not revenue.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-26","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. The government gives producers a subsidy of ₹5 per unit. What does the subsidy cost the government?","options":["₹300","₹330","₹270","₹160"],"answer":1,"explanation":"Sellers receive P + 5: 120 − 2P = 3(P + 5) − 30 → 5P = 135 → P = 27, Q = 66. Cost = 5 × 66 = ₹330. ₹300 uses the pre-subsidy quantity of 60.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-27","question":"The cross-price elasticity between cars and petrol is −0.6. This indicates that the two goods are:","options":["Substitutes","Unrelated goods","Inferior goods","Complements"],"answer":3,"explanation":"Negative cross elasticity: a rise in petrol prices reduces car demand, so they are consumed together (complements).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-28","question":"Along a straight-line demand curve, which statement is correct?","options":["Demand is elastic above the midpoint and inelastic below it","Elasticity is the same at every point because the slope is constant","Demand is inelastic above the midpoint and elastic below it","Demand is unit-elastic at the price-axis intercept"],"answer":0,"explanation":"Elasticity = slope × P/Q. Near the price intercept P/Q is large (elastic); near the quantity intercept it is small (inelastic); at the midpoint it equals −1.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-29","question":"Why is the demand for petrol typically more price elastic in the long run than in the short run?","options":["Consumers have time to switch vehicles, relocate or use other transport","Petrol becomes a luxury good over time","Producers raise output in the long run","The income effect disappears in the long run"],"answer":0,"explanation":"In the short run people are locked into vehicles and habits; given time they can buy efficient or electric vehicles and change travel patterns, so quantity responds more.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-30","question":"A firm sells 1,000 units at ₹100 with a constant marginal cost of ₹40 and no fixed costs. Its demand has a constant price elasticity of −1.5. If it raises its price by 10%, what happens to profit?","options":["It falls from ₹60,000 to about ₹51,000","It rises from ₹60,000 to about ₹60,675","It falls because revenue falls","It is unchanged because the price rise and the quantity fall cancel out"],"answer":1,"explanation":"New quantity = 1,000 × 1.1^(−1.5) = 866.8. Profit = (110 − 40) × 866.8 = ₹60,675 versus (100 − 40) × 1,000 = ₹60,000. Revenue does fall, but the saving in costs on the lost units outweighs it, so profit rises — the price was below the profit-maximising level (P = MC × e/(e − 1) = ₹120).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-31","question":"A buyer was willing to pay up to ₹500 for a concert ticket but bought it for ₹350. What is her consumer surplus?","options":["₹350","₹500","₹150","₹850"],"answer":2,"explanation":"Consumer surplus = willingness to pay − price paid = 500 − 350 = ₹150.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-32","question":"Market demand is P = 100 − 2Q. If the market price is ₹40, what is total consumer surplus?","options":["₹1,800","₹1,200","₹600","₹900"],"answer":3,"explanation":"At P = 40, Q = 30. Consumer surplus = ½ × 30 × (100 − 40) = ₹900. ₹1,800 forgets the ½; ₹1,200 is total spending.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-33","question":"Market demand is P = 100 − 2Q. If the price falls from ₹40 to ₹30, by how much does consumer surplus increase?","options":["₹300","₹350","₹1,225","₹325"],"answer":3,"explanation":"At ₹40: Q = 30, CS = ½ × 30 × 60 = 900. At ₹30: Q = 35, CS = ½ × 35 × 70 = 1,225. Increase = ₹325 = 10 × 30 (old buyers) + ½ × 10 × 5 (new buyers). ₹300 counts only existing buyers.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-34","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. At the market equilibrium, what are producer surplus and total surplus?","options":["Producer surplus ₹900; total surplus ₹1,500","Producer surplus ₹600; total surplus ₹1,800","Producer surplus ₹600; total surplus ₹1,500","Producer surplus ₹1,200; total surplus ₹3,000"],"answer":2,"explanation":"Equilibrium P = 30, Q = 60. Demand reaches zero at P = 60 and supply at P = 10. CS = ½ × 60 × (60 − 30) = 900; PS = ½ × 60 × (30 − 10) = 600; total = ₹1,500.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-35","question":"The law of diminishing marginal returns states that, as more units of a variable input are added to a fixed input:","options":["The extra output from each additional unit eventually falls","Total output eventually falls immediately","Average cost falls continuously","Output rises in the same proportion as all inputs"],"answer":0,"explanation":"With at least one input fixed, marginal product eventually declines. Total output can still be rising. Proportional changes in ALL inputs concern returns to scale, a long-run idea.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-36","question":"Total output with 1 to 5 workers on a fixed plot is 10, 24, 36, 44 and 48 units. What are the marginal product of the 4th worker and the average product with 4 workers?","options":["MP = 11; AP = 8","MP = 8; AP = 11","MP = 12; AP = 11","MP = 8; AP = 9.6"],"answer":1,"explanation":"MP of the 4th worker = 44 − 36 = 8. AP with 4 workers = 44/4 = 11. MPs are 10, 14, 12, 8, 4, so diminishing returns set in after the 2nd worker.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-37","question":"A firm's total cost is TC = 500 + 20Q + Q². At Q = 10, what are average total cost and marginal cost?","options":["ATC = ₹80; MC = ₹30","ATC = ₹30; MC = ₹40","ATC = ₹80; MC = ₹40","ATC = ₹62; MC = ₹40"],"answer":2,"explanation":"TC(10) = 500 + 200 + 100 = 800 → ATC = 80. MC = dTC/dQ = 20 + 2Q = 40. AVC would be 20 + Q = 30.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-38","question":"A firm's total cost is TC = 500 + 20Q + 5Q². At what output is average total cost minimised, and what is the minimum ATC?","options":["Q = 10; ATC = ₹120","Q = 2; ATC = ₹280","Q = 10; ATC = ₹70","Q = 50; ATC = ₹280"],"answer":0,"explanation":"ATC = 500/Q + 20 + 5Q. Setting the derivative to zero: −500/Q² + 5 = 0 → Q = 10. ATC = 50 + 20 + 50 = ₹120. Check: MC = 20 + 10Q = 120 = ATC at that point, as it must be.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-39","question":"A firm's fixed costs are ₹5,000. What happens to average fixed cost when output rises from 100 to 200 units?","options":["It stays at ₹5,000","It rises from ₹25 to ₹50","It falls from ₹50 to ₹0","It falls from ₹50 to ₹25"],"answer":3,"explanation":"AFC = FC/Q: 5,000/100 = 50 and 5,000/200 = 25. AFC keeps falling as output rises but never reaches zero.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-40","question":"A shop earns revenue of ₹20 lakh with explicit costs of ₹14 lakh. The owner gave up a ₹4 lakh salary and has ₹10 lakh of her own capital invested that could earn 8% elsewhere. What are accounting profit and economic profit?","options":["Accounting ₹6 lakh; economic ₹2 lakh","Accounting ₹6 lakh; economic ₹1.2 lakh","Accounting ₹1.2 lakh; economic ₹6 lakh","Accounting ₹6 lakh; economic −₹4.8 lakh"],"answer":1,"explanation":"Accounting profit = 20 − 14 = ₹6 lakh. Implicit costs = 4 + 0.08 × 10 = ₹4.8 lakh. Economic profit = 6 − 4.8 = ₹1.2 lakh. ₹2 lakh forgets the return on capital.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-41","question":"A product sells for ₹500 with a variable cost of ₹300 a unit; fixed costs are ₹3 lakh. How many units must be sold to earn a profit of ₹1 lakh?","options":["1,500 units","1,333 units","800 units","2,000 units"],"answer":3,"explanation":"Required units = (fixed cost + target profit)/contribution per unit = (3,00,000 + 1,00,000)/200 = 2,000. The break-even point alone is 1,500 units.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-42","question":"A perfectly competitive firm faces a price of ₹40. Its minimum average variable cost is ₹45 and its minimum average total cost is ₹55. In the short run it should:","options":["Shut down, because price is below minimum AVC","Keep producing, because it covers part of fixed costs","Raise its price to ₹55","Keep producing until fixed costs are recovered"],"answer":0,"explanation":"If P < min AVC, every unit adds more to cost than to revenue, so producing makes losses larger than the fixed cost; it should shut down. A price-taker cannot raise its price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-43","question":"A competitive firm faces a price of ₹60. At the output where P = MC (1,000 units), its ATC is ₹70 and AVC is ₹50. What should it do in the short run and what is its loss?","options":["Shut down; loss ₹10,000","Continue producing; profit ₹10,000","Continue producing; loss ₹10,000 (versus ₹20,000 if it shut down)","Shut down; loss ₹20,000 is smaller"],"answer":2,"explanation":"Loss if it produces = (70 − 60) × 1,000 = ₹10,000. Fixed cost = (70 − 50) × 1,000 = ₹20,000, which it would lose anyway by shutting down. As P > AVC, producing covers all variable costs and ₹10,000 of fixed costs.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-44","question":"A firm's production function is Q = 4L^0.6 K^0.5. If it doubles both labour and capital, output will:","options":["Exactly double (constant returns to scale)","More than double (increasing returns to scale)","Less than double (decreasing returns to scale)","Rise by a factor of 4"],"answer":1,"explanation":"Doubling inputs multiplies output by 2^(0.6 + 0.5) = 2^1.1 ≈ 2.14. Since the exponents sum to more than 1, returns to scale are increasing. The constant 4 does not affect returns to scale.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-45","question":"A firm's production function is Q = L^0.5 K^0.5. The wage is ₹16 and the rental rate of capital is ₹4. What is the minimum cost of producing 100 units?","options":["₹2,000","₹1,000","₹1,600","₹3,200"],"answer":2,"explanation":"Cost minimisation: MPL/MPK = K/L = w/r = 4 → K = 4L. Then Q = √(L × 4L) = 2L = 100 → L = 50, K = 200. Cost = 16 × 50 + 4 × 200 = 800 + 800 = ₹1,600. Using equal inputs (L = K = 100) costs ₹2,000.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-46","question":"A graduate's best job offer pays ₹10 lakh a year. Instead she joins a 2-year MBA with total fees of ₹20 lakh (ignore discounting and living costs). What is the economic cost of the MBA?","options":["₹20 lakh","₹40 lakh","₹30 lakh","₹10 lakh"],"answer":1,"explanation":"Economic cost = explicit fees + forgone earnings = 20 + 2 × 10 = ₹40 lakh. ₹20 lakh ignores the opportunity cost of time.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-47","question":"A studio has already spent ₹50 crore on a film. Finishing it will cost another ₹20 crore, and it is now expected to earn ₹30 crore in total. What should the studio do?","options":["Abandon it, because total cost (₹70 crore) exceeds revenue (₹30 crore)","Abandon it, because it will lose ₹40 crore","Finish it only if revenue exceeds ₹70 crore","Finish it, because the extra ₹30 crore of revenue exceeds the extra ₹20 crore of cost"],"answer":3,"explanation":"The ₹50 crore is sunk and cannot be recovered either way. Going forward, finishing adds ₹30 crore of revenue for ₹20 crore of cost, a ₹10 crore gain, so finishing reduces the overall loss from ₹50 crore to ₹40 crore.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-48","question":"A bank finds that selling insurance and mutual funds through its existing branches costs less than having separate firms provide each service. This is an example of:","options":["Economies of scope","Economies of scale","Diminishing returns","Diseconomies of scale"],"answer":0,"explanation":"Economies of scope arise when producing several products together is cheaper than producing them separately, usually by sharing inputs such as branches or customer data. Economies of scale concern larger output of the same product.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-49","question":"Assembly follows an 80% learning curve: each time cumulative output doubles, the time for the last unit of the doubled batch falls to 80% of the earlier figure. If the 1st unit takes 100 hours, how long does the 8th unit take?","options":["40.0 hours","64.0 hours","60.0 hours","51.2 hours"],"answer":3,"explanation":"Unit 2 = 80 hours, unit 4 = 64 hours, unit 8 = 51.2 hours (100 × 0.8³). 40 hours subtracts 20% per doubling linearly from the first unit (100 − 3 × 20).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-50","question":"A firm maximises profit at the output where:","options":["Average cost is at its minimum","Marginal revenue equals marginal cost, with MC rising","Total revenue is at its maximum","Price equals average variable cost"],"answer":1,"explanation":"Producing one more unit is worthwhile while MR > MC; profit peaks where MR = MC with MC cutting MR from below. Minimum average cost or maximum revenue are not, in general, the profit-maximising points.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-51","question":"A product's price is ₹250 and its variable cost ₹150 a unit; fixed costs are ₹8 lakh. What are the contribution margin ratio and the break-even sales value?","options":["40%; ₹20 lakh","60%; ₹13.33 lakh","40%; ₹8,000","40%; ₹32 lakh"],"answer":0,"explanation":"CM ratio = (250 − 150)/250 = 40%. Break-even sales = fixed costs/CM ratio = 8 lakh/0.40 = ₹20 lakh (8,000 units × ₹250). ₹8,000 is the break-even volume in units, not value.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-52","question":"Technology A has fixed costs of ₹10 lakh and variable cost ₹60 a unit; technology B has fixed costs of ₹4 lakh and variable cost ₹90 a unit. Which statement is correct?","options":["Total costs are equal at 20,000 units; above that B is cheaper","Total costs are equal at 4,667 units; above that A is cheaper","Total costs are equal at 20,000 units; above that A is cheaper","B is cheaper at every volume because its fixed cost is lower"],"answer":2,"explanation":"10,00,000 + 60Q = 4,00,000 + 90Q → 30Q = 6,00,000 → Q = 20,000. Beyond this volume A's lower variable cost outweighs its higher fixed cost, so the capital-intensive option suits high volumes.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-53","question":"In a competitive industry each firm's long-run total cost is TC = 100 + q². Market demand is Q = 1,000 − 10P. In long-run equilibrium, how many firms will operate?","options":["100","80","60","50"],"answer":1,"explanation":"Long-run price = minimum ATC. ATC = 100/q + q is minimised at q = 10, where ATC = 20. At P = 20, Q = 1,000 − 200 = 800. Number of firms = 800/10 = 80.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-54","question":"When a firm earns 'normal profit', its economic profit is:","options":["Zero","Positive and equal to accounting profit","Negative","Equal to total revenue"],"answer":0,"explanation":"Normal profit is the minimum return needed to keep resources in their current use; it is counted as an implicit cost, so economic profit is zero.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-55","question":"At a firm's current input mix, the marginal product of labour is 20 and that of capital is 40; both a worker and a unit of capital cost ₹10. To minimise the cost of its current output, the firm should:","options":["Use more labour and less capital","Keep the same mix, because the prices are equal","Use more of both","Use more capital and less labour"],"answer":3,"explanation":"Output per rupee: labour 20/10 = 2, capital 40/10 = 4. Shifting spending from labour to capital raises output for the same cost until MPL/w = MPK/r.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-56","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. A ₹5 per-unit tax raises the buyers' price from ₹30 to ₹33 and cuts quantity from 60 to 54. By how much does consumer surplus fall?","options":["₹180","₹162","₹171","₹729"],"answer":2,"explanation":"Demand reaches zero at P = 60. CS before = ½ × 60 × 30 = 900; after = ½ × 54 × 27 = 729. Fall = ₹171 = 3 × 54 (higher price on units still bought) + ½ × 3 × 6 (lost units). ₹162 omits the triangle; ₹729 is the new CS.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-57","question":"In the law of variable proportions, a rational producer operates in the stage where:","options":["Average product is rising","Marginal product is negative","Average product is falling but marginal product is still positive","Total product is falling"],"answer":2,"explanation":"Stage I (rising AP) means the fixed input is under-used; Stage III (negative MP) means too much variable input. Stage II, with falling AP and positive MP, is the rational zone.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-58","question":"Which statements about short-run cost curves are correct? I. MC cuts ATC at the minimum point of ATC. II. AFC rises at high output levels. III. The vertical gap between ATC and AVC narrows as output rises.","options":["I and III only","I, II and III","I and II only","II and III only"],"answer":0,"explanation":"MC passes through the minimum of both AVC and ATC (I). AFC always falls as output rises (II is false). The ATC–AVC gap equals AFC, so it narrows (III).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-59","question":"A firm makes 2,000 components a year at a variable cost of ₹60 each, plus a fixed-overhead allocation of ₹25 each that would remain if production stopped. A supplier offers them at ₹75 each. If the freed capacity could earn ₹40,000 of contribution elsewhere, what should the firm do?","options":["Make: full cost of buying (₹1,50,000) exceeds the variable cost of making (₹1,20,000)","Buy: full cost of making (₹85 each) exceeds ₹75","Make: relevant cost of making is ₹1,20,000 versus ₹1,50,000 to buy","Buy: relevant cost of making is ₹1,60,000 versus ₹1,50,000 to buy"],"answer":3,"explanation":"Unavoidable overhead is irrelevant. Relevant cost of making = 2,000 × 60 + 40,000 opportunity cost = ₹1,60,000; buying costs 2,000 × 75 = ₹1,50,000. Buying saves ₹10,000. The 'full cost' reasoning reaches the right answer for the wrong reason.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-60","question":"If a firm's marginal cost is below its average total cost at the current output, then as output rises slightly:","options":["Average total cost rises","Average total cost falls","Average total cost stays constant","Marginal cost must also fall"],"answer":1,"explanation":"When the marginal unit costs less than the average, it pulls the average down. MC itself may be rising while still below ATC.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-61","question":"Which feature is characteristic of perfect competition?","options":["Each firm faces a downward-sloping demand curve","Firms are price takers selling an identical product","Entry is blocked by patents","A few firms react to each other's prices"],"answer":1,"explanation":"Under perfect competition many small firms sell a homogeneous product with free entry, so each firm takes the market price as given and faces a horizontal demand curve.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-62","question":"A monopolist faces demand P = 100 − 2Q and has a constant marginal cost of ₹20 (no fixed cost). What are its profit-maximising output and price?","options":["Q = 40, P = ₹20","Q = 25, P = ₹50","Q = 20, P = ₹40","Q = 20, P = ₹60"],"answer":3,"explanation":"MR = 100 − 4Q (twice the slope of demand). MR = MC → 100 − 4Q = 20 → Q = 20; P = 100 − 40 = ₹60. Q = 40, P = 20 is the competitive outcome (P = MC).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-63","question":"A monopolist faces demand P = 100 − 2Q with constant MC = ₹20 and charges ₹60 for 20 units. What deadweight loss does it create compared with perfect competition?","options":["₹400","₹800","₹200","₹1,600"],"answer":0,"explanation":"Competitive output: 100 − 2Q = 20 → Q = 40. DWL = ½ × (40 − 20) × (60 − 20) = ₹400. ₹800 forgets the ½ (and equals monopoly profit).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-64","question":"A firm with market power has a marginal cost of ₹60 and faces a price elasticity of demand of −4 at its chosen output. What profit-maximising price does the markup rule imply?","options":["₹75","₹240","₹80","₹64"],"answer":2,"explanation":"P = MC/(1 − 1/|e|) = 60/(1 − 0.25) = 60/0.75 = ₹80. ₹75 adds 25% to MC instead of dividing by 0.75.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-65","question":"A firm sells at ₹80 with a marginal cost of ₹60. If it is maximising profit, what is its Lerner index, and what elasticity of demand does that imply?","options":["0.25; elasticity −4","0.33; elasticity −3","0.25; elasticity −0.25","0.75; elasticity −1.33"],"answer":0,"explanation":"Lerner index = (P − MC)/P = 20/80 = 0.25. At the profit maximum it equals 1/|e|, so |e| = 4. 0.33 divides the markup by MC instead of price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-66","question":"A monopolist with constant MC = ₹20 sells in two separate markets: A with demand P = 100 − Q and B with demand P = 60 − Q. If it price-discriminates, what prices does it charge?","options":["₹50 in both markets","₹60 in A and ₹40 in B","₹40 in A and ₹60 in B","₹60 in A and ₹20 in B"],"answer":1,"explanation":"Set MR = MC in each market. A: 100 − 2Q = 20 → Q = 40, P = 60. B: 60 − 2Q = 20 → Q = 20, P = 40. The higher price goes to the market with less elastic demand at the optimum.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-67","question":"The same monopolist (MC = ₹20; market A: P = 100 − Q; market B: P = 60 − Q) is banned from discriminating and must charge one price. How much profit does the ban cost it?","options":["₹400 (profit falls from ₹2,000 to ₹1,600)","Nothing; uniform pricing gives the same ₹2,000","₹200 (profit falls from ₹1,800 to ₹1,600)","₹200 (profit falls from ₹2,000 to ₹1,800)"],"answer":3,"explanation":"Discrimination profit = 40 × 40 + 20 × 20 = ₹2,000. Uniform price: combined demand Q = 160 − 2P (for P ≤ 60) → P = 80 − Q/2, MR = 80 − Q = 20 → Q = 60, P = ₹50 (A buys 50, B buys 10). Profit = 30 × 60 = ₹1,800. Loss = ₹200.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-68","question":"Two identical firms compete by choosing quantities (Cournot). Market demand is P = 120 − Q and each has a constant MC of ₹30. What is the equilibrium market price?","options":["₹75","₹30","₹60","₹52.50"],"answer":2,"explanation":"Firm 1's best response: q₁ = (90 − q₂)/2. With symmetry q = (120 − 30)/3 = 30 each, so Q = 60 and P = ₹60. A monopoly would charge ₹75; Bertrand competition would drive price to ₹30; ₹52.50 is the Stackelberg price.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-69","question":"With market demand P = 120 − Q and MC = ₹30 for both firms, firm 1 chooses its quantity first and firm 2 then responds (Stackelberg). What are the outputs of the leader and the follower?","options":["Leader 30, follower 30","Leader 45, follower 45","Leader 22.5, follower 45","Leader 45, follower 22.5"],"answer":3,"explanation":"Follower's best response: q₂ = (90 − q₁)/2. Leader maximises (120 − q₁ − q₂ − 30)q₁ = (45 − q₁/2)q₁ → q₁ = 45, so q₂ = 22.5 and P = 120 − 67.5 = ₹52.50. The leader produces more than under Cournot (30).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-70","question":"The kinked demand curve model of oligopoly is used to explain:","options":["Why oligopolists always form cartels","Why prices tend to stay rigid even when costs change","Why oligopoly prices equal marginal cost","Why entry is free in oligopoly"],"answer":1,"explanation":"Rivals match price cuts but not price rises, so demand is elastic above the current price and inelastic below it. MR has a gap at the kink, so moderate cost changes leave the profit-maximising price unchanged.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-71","question":"Assertion (A): Cartels tend to be unstable. Reason (R): Each member can raise its own profit by secretly producing more than its quota at the cartel price.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. The incentive to cheat is the prisoner's dilemma inside every cartel; detection and punishment problems make it break down.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-72","question":"Four firms in an industry have market shares of 40%, 30%, 20% and 10%. What is the Herfindahl–Hirschman Index?","options":["100","2,500","3,000","1,000"],"answer":2,"explanation":"HHI = 40² + 30² + 20² + 10² = 1,600 + 900 + 400 + 100 = 3,000. 100 just adds the shares.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-73","question":"In an industry with shares of 40%, 30%, 20% and 10%, the two smallest firms merge (and keep their combined share). By how much does the HHI rise?","options":["400 points, from 3,000 to 3,400","300 points, from 3,000 to 3,300","200 points, from 3,000 to 3,200","500 points, from 3,000 to 3,500"],"answer":0,"explanation":"New shares: 40, 30, 30 → HHI = 1,600 + 900 + 900 = 3,400. The increase always equals 2 × s₁ × s₂ = 2 × 20 × 10 = 400.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-74","question":"Restaurants in a city — many sellers, each offering a slightly different menu, with easy entry — best illustrate:","options":["Perfect competition","Oligopoly","Monopolistic competition","Monopoly"],"answer":2,"explanation":"Many firms, differentiated products and free entry are the defining features of monopolistic competition.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-75","question":"In long-run equilibrium under monopolistic competition, which statement is correct?","options":["Firms earn positive economic profit protected by entry barriers","Firms earn zero economic profit and price exceeds marginal cost, leaving excess capacity","Price equals marginal cost and minimum average cost","Firms produce at the minimum of their long-run average cost"],"answer":1,"explanation":"Entry pushes each firm's demand curve until it is tangent to ATC: P = ATC (zero profit) but on the falling part of ATC, so P > MC and output is below the minimum-cost scale.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-76","question":"Two firms each choose a High or Low price. Payoffs (firm A, firm B) in ₹ crore: both High (50, 50); A High, B Low (10, 70); A Low, B High (70, 10); both Low (30, 30). What is the Nash equilibrium?","options":["Both choose High, earning ₹50 crore each","A High and B Low","There is no Nash equilibrium","Both choose Low, earning ₹30 crore each"],"answer":3,"explanation":"Low is dominant for each firm: if the rival is High, Low gives 70 > 50; if the rival is Low, Low gives 30 > 10. So both choose Low — a prisoner's dilemma, since both would prefer (50, 50).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-77","question":"Firms A and B decide whether to advertise. Payoffs (A, B): both advertise (40, 30); only A advertises (60, 20); only B advertises (30, 40); neither (50, 35). Which statement is correct?","options":["Both advertise, although both would earn more if neither did","Neither advertises, because (50, 35) is better for both","Only A advertises, because A gets its highest payoff","There are two Nash equilibria: both advertise and neither advertises"],"answer":0,"explanation":"A: advertising gives 40 > 30 (if B advertises) and 60 > 50 (if B does not) — dominant. B: 30 > 20 and 40 > 35 — dominant. Equilibrium (40, 30), yet (50, 35) would be better for both: a prisoner's dilemma.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-78","question":"Two firms choose a technology standard. Payoffs (A, B): both X (60, 40); both Y (40, 60); A X and B Y (0, 0); A Y and B X (0, 0). How many pure-strategy Nash equilibria are there?","options":["One: both X","One: both Y","Two: both X and both Y","None"],"answer":2,"explanation":"At (X, X) neither gains by switching (0 < 60, 0 < 40); the same holds at (Y, Y). Mismatched choices give zero, so each firm wants to switch. This coordination game has two equilibria, each favouring a different firm.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-79","question":"Player A chooses Up or Down; player B chooses Left, Middle or Right. Payoffs (A, B): Up–Left (4, 3), Up–Middle (5, 1), Up–Right (6, 2), Down–Left (2, 1), Down–Middle (8, 4), Down–Right (3, 6). What is the outcome after iterated elimination of strictly dominated strategies?","options":["Down–Middle, with payoffs (8, 4)","Down–Right, with payoffs (3, 6)","Up–Right, with payoffs (6, 2)","Up–Left, with payoffs (4, 3)"],"answer":3,"explanation":"For B, Right beats Middle in both rows (2 > 1, 6 > 4), so delete Middle. Then for A, Up beats Down against Left (4 > 2) and Right (6 > 3), so delete Down. Facing Up, B prefers Left (3 > 2). The unique equilibrium is Up–Left. Down–Middle has the largest total payoff but is not stable.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-80","question":"A potential entrant decides whether to Enter. If it stays out, payoffs are (entrant 0, incumbent 100). If it enters, the incumbent chooses Fight (−10, 20) or Accommodate (30, 50). Using backward induction, what happens?","options":["The entrant stays out because it fears a fight","The entrant enters and the incumbent accommodates","The entrant enters and the incumbent fights","The entrant stays out and the incumbent earns 100"],"answer":1,"explanation":"Once entry has happened, the incumbent prefers Accommodate (50 > 20), so a threat to fight is not credible. Anticipating this, the entrant compares 30 with 0 and enters.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-81","question":"In an infinitely repeated pricing game, each period's payoffs are: both cooperate 50 each, both cheat 30 each, and a lone cheater gets 70 (the other 10). With grim-trigger strategies, what is the minimum discount factor that sustains cooperation?","options":["0.40","0.50","0.67","0.29"],"answer":1,"explanation":"Cooperation is stable if 50/(1 − δ) ≥ 70 + 30δ/(1 − δ) → 50 ≥ 70(1 − δ) + 30δ → δ ≥ (70 − 50)/(70 − 30) = 0.5. Players must value the future at least half as much as today.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-82","question":"Which conditions are needed for a firm to practise third-degree price discrimination profitably? I. It has some market power. II. It can separate buyers into groups. III. The groups have different price elasticities. IV. Buyers cannot resell easily.","options":["I, II, III and IV","I, II and III only","II, III and IV only","I and IV only"],"answer":0,"explanation":"All four are needed: a price-taker cannot discriminate, groups must be identifiable, differing elasticities make different prices profitable, and resale would undo the price differences.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-83","question":"In long-run equilibrium in a perfectly competitive industry, which set of conditions holds?","options":["P = MC > minimum ATC, with positive economic profit","P > MC = minimum ATC","P = MC = minimum ATC, with zero economic profit","P = AVC, with firms just covering variable costs"],"answer":2,"explanation":"Free entry and exit eliminate economic profit, so price falls to minimum ATC, where MC = ATC. Firms produce at efficient scale and allocative efficiency (P = MC) holds.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-84","question":"A water utility's long-run average cost falls over the whole range of market demand. If a regulator forces it to price at marginal cost, what happens?","options":["It earns a normal profit","It earns supernormal profit","Output falls below the monopoly level","It makes a loss, because MC lies below average cost when AC is falling"],"answer":3,"explanation":"With falling AC, MC < AC, so P = MC does not cover average cost. This is the natural-monopoly pricing dilemma: regulators often use average-cost pricing or subsidies instead.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-85","question":"A gym has identical members, each with demand for visits q = 10 − P, and a marginal cost of ₹2 per visit. With a two-part tariff (membership fee plus per-visit price), what fee maximises profit?","options":["₹50 per member, with a per-visit price of ₹0","₹32 per member, with a per-visit price of ₹2","₹18 per member, with a per-visit price of ₹4","₹32 per member, with a per-visit price of ₹6"],"answer":1,"explanation":"Set the per-visit price at MC = ₹2, so each member makes 8 visits; then capture all consumer surplus with the fee: ½ × 8 × (10 − 2) = ₹32. Profit per member = ₹32. A ₹4 price with an ₹18 fee yields only 18 + 2 × 6 = ₹30.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-86","question":"Two firms sell identical products with the same constant marginal cost of ₹30 and compete by setting prices simultaneously (Bertrand). What is the equilibrium price?","options":["The monopoly price","Halfway between ₹30 and the monopoly price","Any price above ₹30","₹30"],"answer":3,"explanation":"Each firm can capture the whole market by undercutting slightly, so any price above MC is undercut. The only equilibrium is P = MC = ₹30 — the Bertrand paradox: two firms are enough for the competitive outcome.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-87","question":"A firm launching an innovative gadget sets a high initial price for early adopters and cuts it over time. This strategy is called:","options":["Penetration pricing","Predatory pricing","Price skimming","Cost-plus pricing"],"answer":2,"explanation":"Skimming captures surplus from buyers with high willingness to pay before targeting more price-sensitive segments. Penetration pricing starts low to build share quickly.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-88","question":"A software firm has two customers. A values Writer at ₹120 and Sheets at ₹100; B values Writer at ₹100 and Sheets at ₹150. Marginal cost is zero. How much more revenue does pure bundling earn than the best separate prices?","options":["₹40 (₹440 versus ₹400)","₹70 (₹470 versus ₹400)","₹0 (both give ₹400)","₹20 (₹440 versus ₹420)"],"answer":0,"explanation":"Separate: Writer at ₹100 sells to both (₹200 > ₹120); Sheets at ₹100 sells to both (₹200 > ₹150): total ₹400. Bundle: A values it at ₹220, B at ₹250, so a ₹220 bundle sells to both: ₹440. Bundling works because the valuations are negatively correlated. ₹470 is total willingness to pay.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-89","question":"A monopolist with demand P = 100 − 2Q and constant MC = ₹20 must pay a new tax of ₹10 per unit. By how much does its price rise?","options":["₹10 (from ₹60 to ₹70)","₹2.50 (from ₹60 to ₹62.50)","₹5 (from ₹60 to ₹65)","₹0, because a monopolist absorbs the tax"],"answer":2,"explanation":"New MC = 30: 100 − 4Q = 30 → Q = 17.5, P = 100 − 35 = ₹65. With linear demand and constant MC, a monopolist passes on half of a per-unit tax.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-90","question":"Which feature most distinguishes oligopoly from other market structures?","options":["Strategic interdependence: each firm's best decision depends on rivals' reactions","Many sellers of a homogeneous product","A single seller with no close substitutes","Zero economic profit in the long run"],"answer":0,"explanation":"With a few large firms, each must anticipate rivals' responses to its price, output or advertising — the reason game theory is used to study oligopoly.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-91","question":"Under the expenditure method, GDP equals:","options":["C + S + T","C + I + G + (X − M)","C + I + G + X + M","Wages + rent + interest + profit − depreciation"],"answer":1,"explanation":"GDP = consumption + investment + government purchases + net exports. Imports are subtracted because they are produced abroad.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-92","question":"An economy has consumption ₹600 crore, investment ₹200 crore, government purchases ₹150 crore, exports ₹100 crore and imports ₹120 crore. What is GDP?","options":["₹1,170 crore","₹950 crore","₹1,050 crore","₹930 crore"],"answer":3,"explanation":"GDP = 600 + 200 + 150 + (100 − 120) = ₹930 crore. ₹1,170 crore adds imports instead of subtracting them.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-93","question":"GDP at market prices is ₹930 crore, net factor income from abroad is −₹20 crore, depreciation ₹60 crore, indirect taxes ₹90 crore and subsidies ₹30 crore. What is national income (NNP at factor cost)?","options":["₹850 crore","₹830 crore","₹910 crore","₹790 crore"],"answer":3,"explanation":"GNP_MP = 930 − 20 = 910; NNP_MP = 910 − 60 = 850; NNP_FC = 850 − 90 + 30 = ₹790 crore. ₹850 crore stops at market prices; ₹830 crore adds NFIA instead of subtracting it.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-94","question":"A farmer sells wheat worth ₹100 to a miller, the miller sells flour worth ₹160 to a baker, and the baker sells bread worth ₹250 to consumers. How much do these transactions add to GDP?","options":["₹510","₹250","₹160","₹90"],"answer":1,"explanation":"Only the final good counts (₹250); equivalently, the values added are 100 + 60 + 90 = 250. Adding all sales (₹510) double-counts intermediate goods. ₹90 is the baker's value added alone.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-95","question":"Which of these is NOT included in GDP?","options":["Old-age pension paid by the government","Salary paid to a government teacher","A new factory built by a company","Services exported by an IT firm"],"answer":0,"explanation":"Pensions are transfer payments: no current good or service is produced in return. Government salaries, new investment and exports are all part of GDP.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-96","question":"Nominal GDP this year is ₹220 lakh crore and the GDP deflator is 110 (base year = 100). Real GDP last year was ₹190 lakh crore. What was real GDP growth this year?","options":["15.79%","10.00%","5.26%","5.79%"],"answer":2,"explanation":"Real GDP = 220/1.10 = ₹200 lakh crore. Growth = 200/190 − 1 = 5.26%. 15.79% compares nominal with real values, and 5.79% subtracts the 10% price rise from that, a rough approximation on the wrong base.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-97","question":"Nominal GDP is ₹1,200 crore and real GDP (at base-year prices) is ₹1,000 crore. What is the GDP deflator?","options":["83.3","20","120","220"],"answer":2,"explanation":"GDP deflator = nominal/real × 100 = 1,200/1,000 × 100 = 120, meaning the price level is 20% above the base year.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-98","question":"In a simple closed economy without taxes, the marginal propensity to consume is 0.8. By how much does income rise if investment increases by ₹100 crore?","options":["₹80 crore","₹125 crore","₹180 crore","₹500 crore"],"answer":3,"explanation":"Multiplier = 1/(1 − MPC) = 1/0.2 = 5, so ΔY = 5 × 100 = ₹500 crore. ₹125 crore uses 1/MPC.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-99","question":"The MPC out of disposable income is 0.8 and the proportional income tax rate is 25%. In a closed economy, by how much does income rise when investment increases by ₹40 crore?","options":["₹100 crore","₹200 crore","₹160 crore","₹53.3 crore"],"answer":0,"explanation":"Multiplier = 1/[1 − MPC(1 − t)] = 1/(1 − 0.8 × 0.75) = 1/0.4 = 2.5 → ΔY = 2.5 × 40 = ₹100 crore. ₹200 crore ignores the tax leakage.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-100","question":"The MPC out of disposable income is 0.8, the tax rate is 25% and the marginal propensity to import is 0.1. By how much does income rise if government spending increases by ₹50 crore?","options":["₹125 crore","₹100 crore","₹250 crore","₹83.3 crore"],"answer":1,"explanation":"Multiplier = 1/[1 − MPC(1 − t) + MPM] = 1/(1 − 0.6 + 0.1) = 1/0.5 = 2. ΔY = 2 × 50 = ₹100 crore. ₹125 crore ignores imports; ₹250 crore ignores both taxes and imports.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-101","question":"With an MPC of 0.8 and lump-sum taxes, by how much does equilibrium income change if the government cuts taxes by ₹25 crore?","options":["Rises by ₹100 crore","Rises by ₹125 crore","Rises by ₹20 crore","Falls by ₹100 crore"],"answer":0,"explanation":"Tax multiplier = −MPC/(1 − MPC) = −0.8/0.2 = −4. A tax cut of 25 raises income by 4 × 25 = ₹100 crore. It is smaller than the spending multiplier (5) because part of the tax cut is saved.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-102","question":"Assertion (A): If the government raises spending and lump-sum taxes by the same ₹100 crore, equilibrium income rises by ₹100 crore. Reason (R): The tax multiplier is smaller in absolute value than the spending multiplier by exactly 1.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Spending multiplier 1/(1 − c) minus tax multiplier c/(1 − c) equals 1, so the balanced-budget multiplier is 1 and income rises by exactly ₹100 crore. R gives the reason, so it explains A.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-103","question":"In a closed economy, C = 100 + 0.75(Y − T), lump-sum taxes T = 40, investment I = 150 and government spending G = 100 (₹ crore). What is equilibrium income?","options":["₹1,400 crore","₹1,360 crore","₹1,280 crore","₹1,240 crore"],"answer":2,"explanation":"Y = 100 + 0.75(Y − 40) + 150 + 100 → Y − 0.75Y = 350 − 30 → 0.25Y = 320 → Y = ₹1,280 crore. Ignoring taxes gives ₹1,400 crore.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-104","question":"Equilibrium income is ₹1,280 crore but full-employment income is ₹1,500 crore. With an MPC of 0.75 and lump-sum taxes, by how much must government spending rise to close the gap?","options":["₹220 crore","₹55 crore","₹73.3 crore","₹165 crore"],"answer":1,"explanation":"Spending multiplier = 1/(1 − 0.75) = 4. Required ΔG = 220/4 = ₹55 crore. A tax cut would need to be larger: 220/3 = ₹73.3 crore.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-105","question":"Assertion (A): If all households try to save more during a recession, total saving in the economy may not rise. Reason (R): Lower consumption reduces income through the multiplier, and saving depends on income.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This is the paradox of thrift. Higher planned saving cuts demand and income, so actual saving may not rise (it can even fall if investment responds to income). R explains A.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-106","question":"If the marginal propensity to save is 0.25, what are the MPC and the simple investment multiplier?","options":["MPC 0.25; multiplier 4","MPC 0.75; multiplier 1.33","MPC 0.75; multiplier 0.25","MPC 0.75; multiplier 4"],"answer":3,"explanation":"MPC + MPS = 1, so MPC = 0.75. Multiplier = 1/MPS = 4. 1.33 is 1/MPC.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-107","question":"A consumption function is C = 200 + 0.6Y. At income Y = 1,000, what are the average and marginal propensities to consume?","options":["APC 0.6; MPC 0.8","APC 0.6; MPC 0.6","APC 0.8; MPC 0.6","APC 0.8; MPC 0.8"],"answer":2,"explanation":"C = 200 + 600 = 800, so APC = 800/1,000 = 0.8. MPC = slope = 0.6. With positive autonomous consumption, APC exceeds MPC.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-108","question":"Firms keep a capital–output ratio of 3. If annual output rises from ₹400 crore to ₹450 crore, how much net investment does the accelerator principle predict?","options":["₹50 crore","₹1,350 crore","₹16.7 crore","₹150 crore"],"answer":3,"explanation":"Net investment = capital–output ratio × change in output = 3 × 50 = ₹150 crore. ₹1,350 crore is the total capital needed for the new output, not the addition.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-109","question":"Real GDP grows by 7% and population by 1.5% in a year. By how much does real GDP per capita grow?","options":["5.50%","5.42%","8.50%","8.60%"],"answer":1,"explanation":"(1 + per-capita growth) = 1.07/1.015 → growth = 5.42%. 5.50% is the quick approximation (7 − 1.5).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-110","question":"Nominal GDP rises from ₹500 crore to ₹572 crore while the GDP deflator rises from 100 to 104. What is real GDP growth?","options":["14.40%","10.40%","4.00%","10.00%"],"answer":3,"explanation":"Real GDP in year 2 = 572/1.04 = ₹550 crore. Growth = 550/500 − 1 = 10%. 14.4% is nominal growth; 10.4% subtracts inflation from nominal growth, an approximation.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-111","question":"An economy has compensation of employees ₹500 crore, operating surplus ₹300 crore, mixed income of the self-employed ₹100 crore, depreciation ₹50 crore and net indirect taxes ₹70 crore (net factor income from abroad is zero). What is GDP at market prices?","options":["₹900 crore","₹970 crore","₹1,020 crore","₹950 crore"],"answer":2,"explanation":"Income method: NDP at factor cost = 500 + 300 + 100 = 900. GDP_MP = NDP_FC + depreciation + net indirect taxes = 900 + 50 + 70 = ₹1,020 crore. ₹900 crore is domestic income; ₹970 crore omits depreciation.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-112","question":"Which transaction is counted in this year's GDP?","options":["The sale of a second-hand car","A new house built and sold this year","The purchase of shares in a listed company","A gift of money from a relative abroad"],"answer":1,"explanation":"A newly built house is investment in current output. Second-hand sales were counted when first produced; shares are financial transfers; gifts are transfers.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-113","question":"In an open economy at equilibrium, planned saving is ₹120 crore, taxes ₹100 crore, imports ₹80 crore, investment ₹110 crore and government spending ₹120 crore. What must exports be?","options":["₹90 crore","₹300 crore","₹70 crore","₹50 crore"],"answer":2,"explanation":"At equilibrium, leakages equal injections: S + T + M = I + G + X → 120 + 100 + 80 = 110 + 120 + X → X = ₹70 crore.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-114","question":"A government's revenue receipts are ₹20 lakh crore, non-debt capital receipts ₹1 lakh crore, revenue expenditure ₹25 lakh crore, capital expenditure ₹5 lakh crore and interest payments ₹8 lakh crore. What are the primary deficit and the revenue deficit?","options":["Primary deficit ₹9 lakh crore; revenue deficit ₹5 lakh crore","Primary deficit ₹1 lakh crore; revenue deficit ₹10 lakh crore","Primary deficit ₹2 lakh crore; revenue deficit ₹4 lakh crore","Primary deficit ₹1 lakh crore; revenue deficit ₹5 lakh crore"],"answer":3,"explanation":"Fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts) = 30 − 21 = 9. Primary deficit = 9 − 8 = ₹1 lakh crore. Revenue deficit = 25 − 20 = ₹5 lakh crore. ₹9 lakh crore is the fiscal deficit.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-115","question":"When higher government borrowing pushes up interest rates and reduces private investment, the effect is called:","options":["Crowding out","The accelerator effect","The paradox of thrift","Demand-pull inflation"],"answer":0,"explanation":"Government competes with private borrowers for loanable funds; higher rates crowd out interest-sensitive private investment, reducing the net effect of fiscal expansion.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-116","question":"Reserve money (high-powered money) is ₹100 lakh crore. Banks hold reserves equal to 10% of deposits and the public holds currency equal to 20% of deposits. What is broad money supply in this simple model?","options":["₹1,000 lakh crore","₹400 lakh crore","₹333 lakh crore","₹600 lakh crore"],"answer":1,"explanation":"Money multiplier = (1 + c)/(c + r) = 1.2/0.3 = 4. Money supply = 4 × 100 = ₹400 lakh crore. ₹1,000 lakh crore ignores currency drain (1/r).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-117","question":"Which index measures changes in the prices of a basket of goods and services bought by households?","options":["Index of Industrial Production","Wholesale Price Index","Consumer Price Index","Sensex"],"answer":2,"explanation":"The CPI tracks retail prices paid by consumers. The WPI tracks wholesale prices of goods; the IIP measures industrial output; the Sensex is a share price index.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-118","question":"GDP at market prices is ₹1,000 crore, indirect taxes are ₹120 crore and subsidies ₹20 crore. What is GDP at factor cost?","options":["₹900 crore","₹860 crore","₹1,100 crore","₹880 crore"],"answer":0,"explanation":"GDP_FC = GDP_MP − indirect taxes + subsidies = 1,000 − 120 + 20 = ₹900 crore. ₹860 crore subtracts subsidies too.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-119","question":"The MPC is 0.6. The government spends an extra ₹100 crore. How much has total income risen after the first three rounds of spending, and what is the eventual total increase?","options":["₹160 crore after three rounds; ₹250 crore eventually","₹196 crore after three rounds; ₹250 crore eventually","₹196 crore after three rounds; ₹166.7 crore eventually","₹216 crore after three rounds; ₹250 crore eventually"],"answer":1,"explanation":"Rounds: 100 + 60 + 36 = ₹196 crore. The full multiplier is 1/(1 − 0.6) = 2.5, so the eventual rise is ₹250 crore. ₹166.7 crore uses 1/MPC.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-120","question":"A car maker produces 1,000 cars this year but sells only 900; the rest stay in its warehouse. How do the unsold cars enter this year's GDP?","options":["They are excluded until they are sold","They are counted as consumption","They are subtracted as a loss","As investment in inventories, so all 1,000 cars count"],"answer":3,"explanation":"GDP measures production. Unsold output is recorded as inventory investment, so all 1,000 cars count this year; next year's sale of these cars will not add to GDP again.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-121","question":"Inflation caused by aggregate demand growing faster than the economy's productive capacity is called:","options":["Cost-push inflation","Demand-pull inflation","Deflation","Stagflation"],"answer":1,"explanation":"Too much spending chasing too few goods pulls prices up. Cost-push inflation comes from rising input costs such as wages or oil.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-122","question":"A consumer basket cost ₹2,400 in the base year and costs ₹2,580 now. What are the price index and the inflation rate since the base year?","options":["Index 107.5; inflation 7.5%","Index 93.0; inflation −7.0%","Index 107.5; inflation 180%","Index 180; inflation 7.5%"],"answer":0,"explanation":"Index = 2,580/2,400 × 100 = 107.5, so prices are 7.5% higher than in the base year.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-123","question":"Base-year quantities are 10 units of A and 4 units of B. Prices of A rose from ₹5 to ₹6 and of B from ₹20 to ₹22. What is the Laspeyres price index?","options":["115.00","87.84","112.86","113.85"],"answer":3,"explanation":"Laspeyres uses base-year quantities: (10 × 6 + 4 × 22)/(10 × 5 + 4 × 20) × 100 = 148/130 × 100 = 113.85. 115.00 is an unweighted average of price relatives.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-124","question":"Prices of A rose from ₹5 to ₹6 and of B from ₹20 to ₹22. Base-year quantities were 10 of A and 4 of B; current-year quantities are 8 of A and 5 of B. What is the Paasche price index?","options":["113.85","113.35","112.86","121.54"],"answer":2,"explanation":"Paasche uses current quantities: (8 × 6 + 5 × 22)/(8 × 5 + 5 × 20) × 100 = 158/140 × 100 = 112.86. 113.85 is the Laspeyres index and 113.35 is Fisher's ideal index (their geometric mean); 121.54 mixes current and base quantities.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-125","question":"A fixed deposit pays 9% a year while inflation is 5%. What is the exact real interest rate?","options":["4.00%","3.81%","14.45%","1.80%"],"answer":1,"explanation":"Real rate = 1.09/1.05 − 1 = 3.81%. 4% is the approximation (9 − 5).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-126","question":"If inflation runs at 6% a year for 5 years, what will ₹1,00,000 then be worth in today's purchasing power?","options":["₹74,726","₹70,000","₹73,390","₹76,923"],"answer":0,"explanation":"Real value = 1,00,000/1.06⁵ = 1,00,000/1.33823 = ₹74,726. ₹70,000 subtracts 6% a year in simple terms; ₹73,390 applies a 6% fall each year, which is not the same as dividing by 1.06.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-127","question":"When the central bank buys government securities in the open market, what happens to bank reserves and money supply?","options":["Both decrease","Reserves increase but money supply falls","Both increase","Neither changes, because only ownership of bonds changes"],"answer":2,"explanation":"The central bank pays for the securities by crediting banks' reserve accounts, so reserves rise and banks can lend more, expanding money supply.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-128","question":"Match each monetary tool with its type. (p) Changing the cash reserve ratio, (q) Margin requirements on loans against specific commodities, (r) Open market operations, (s) Moral suasion. Types: (1) Quantitative, (2) Qualitative/selective.","options":["p-2, q-1, r-1, s-2","p-1, q-1, r-2, s-2","p-1, q-2, r-2, s-1","p-1, q-2, r-1, s-2"],"answer":3,"explanation":"Reserve ratios and open market operations change the overall volume of credit (quantitative). Margin requirements and moral suasion direct credit to or away from particular uses (qualitative).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-129","question":"Which combination of measures is contractionary (anti-inflationary) monetary policy?","options":["Cut the policy rate, buy government securities and cut the reserve ratio","Raise the policy rate, buy government securities and cut the reserve ratio","Cut taxes, raise spending and raise the policy rate","Raise the policy rate, sell government securities and raise the reserve ratio"],"answer":3,"explanation":"All three tighten liquidity and raise the cost of credit. Buying securities or cutting reserve ratios injects liquidity; tax and spending changes are fiscal, not monetary, tools.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-130","question":"Under the quantity theory (MV = PY), money supply grows by 10%, velocity is constant and real output grows by 6%. What is the inflation rate?","options":["4.00%","16.00%","3.77%","10.00%"],"answer":2,"explanation":"(1 + π) = (1 + ΔM)(1 + ΔV)/(1 + ΔY) = 1.10 × 1/1.06 → π = 3.77%. 4% is the approximation 10 − 6.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-131","question":"A central bank follows the rule i = r* + π + 0.5(π − π*) + 0.5 × (output gap). The neutral real rate r* is 2%, inflation 6%, the target 4% and output is 1% below potential. What policy rate does the rule suggest?","options":["9.5%","8.5%","7.5%","8.0%"],"answer":1,"explanation":"i = 2 + 6 + 0.5 × (6 − 4) + 0.5 × (−1) = 2 + 6 + 1 − 0.5 = 8.5%. 9.5% treats the negative output gap as positive.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-132","question":"Assertion (A): In the short run, policies that lower unemployment may raise inflation. Reason (R): The short-run Phillips curve shows an inverse relationship between inflation and unemployment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. In the long run, as expectations adjust, the Phillips curve becomes vertical at the natural rate of unemployment.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-133","question":"Stagflation refers to a situation of:","options":["Falling prices and rising output","High growth with low inflation","Rising prices caused only by excess demand","High inflation together with stagnant output and high unemployment"],"answer":3,"explanation":"Stagflation combines inflation with weak growth and unemployment, usually from a supply shock, which makes demand management difficult.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-134","question":"Fiscal policy works mainly through:","options":["Government spending and taxation","The policy repo rate","Reserve requirements on banks","Open market operations"],"answer":0,"explanation":"Fiscal policy is run by the government through its budget. Interest rates, reserve ratios and open market operations are monetary policy tools.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-135","question":"Which of these act as automatic stabilisers? I. A progressive income tax. II. Unemployment benefits. III. A one-time stimulus package voted by parliament.","options":["I, II and III","I and II only","III only","II and III only"],"answer":1,"explanation":"Automatic stabilisers change without new decisions: tax collections fall and benefit payments rise in a downturn. A specially approved stimulus is discretionary fiscal policy.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-136","question":"In a year, a country's merchandise exports are ₹300 crore and imports ₹420 crore; net services exports are +₹80 crore, net transfers (remittances) +₹60 crore and net primary income −₹30 crore. What is its current account balance?","options":["Deficit of ₹120 crore","Surplus of ₹20 crore","Deficit of ₹10 crore","Deficit of ₹40 crore"],"answer":2,"explanation":"Current account = trade balance (−120) + services (+80) + transfers (+60) + primary income (−30) = −₹10 crore. −₹120 crore is only the merchandise trade deficit.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-137","question":"A country has a current account deficit of ₹10 crore, net FDI inflows of ₹25 crore, net portfolio outflows of ₹5 crore and other net capital inflows of ₹10 crore. Ignoring errors and omissions, what happens to its foreign exchange reserves?","options":["They fall by ₹20 crore","They rise by ₹20 crore","They rise by ₹30 crore","They fall by ₹10 crore"],"answer":1,"explanation":"Capital/financial account = 25 − 5 + 10 = +30. Overall balance = −10 + 30 = +20, which shows up as a ₹20 crore addition to reserves. ₹30 crore ignores the current account deficit.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-138","question":"A country's merchandise trade deficit is large, yet its current account is close to balance. The most likely reason is:","options":["Large foreign direct investment inflows","A rise in foreign exchange reserves","A large fiscal deficit","Large surpluses on services and remittances"],"answer":3,"explanation":"The current account adds services, primary income and transfers to the goods balance. FDI and reserves belong to the capital/financial account side, not the current account.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-139","question":"The rupee moves from ₹80 to ₹84 per US dollar. By what percentage has the rupee depreciated against the dollar, and the dollar appreciated against the rupee?","options":["Rupee −4.76%; dollar +5.00%","Rupee −5.00%; dollar +5.00%","Rupee −5.00%; dollar +4.76%","Rupee −4.00%; dollar +4.00%"],"answer":0,"explanation":"Dollar value in rupees: 84/80 − 1 = +5%. Rupee value in dollars: (1/84)/(1/80) − 1 = 80/84 − 1 = −4.76%. The two percentages differ because the bases differ.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-140","question":"A standard basket costs ₹4,000 in India and $60 in the US, while the market exchange rate is ₹80 per dollar. Which statement is correct?","options":["The PPP rate is ₹66.67 per dollar, so the rupee is overvalued at the market rate","The PPP rate is ₹120 per dollar, so the rupee is overvalued","The PPP rate is ₹66.67 per dollar, so the rupee is undervalued at the market rate","The PPP rate equals the market rate"],"answer":2,"explanation":"PPP rate = 4,000/60 = ₹66.67 per $. At the market rate ₹80, a dollar buys more in India than PPP implies, so the rupee is weaker (undervalued) than PPP suggests.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-141","question":"Inflation is expected to be 6% in India and 2% in the US. The spot rate is ₹80 per dollar. According to relative purchasing power parity, what is the expected exchange rate one year later?","options":["₹83.14 per $","₹83.20 per $","₹76.98 per $","₹84.80 per $"],"answer":0,"explanation":"Expected rate = 80 × 1.06/1.02 = ₹83.14. The higher-inflation currency depreciates by about the inflation difference. ₹83.20 is the approximation 80 × 1.04.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-142","question":"A country's trade is initially balanced. The price elasticity of demand for its exports is 0.4 and for its imports 0.5. If its currency depreciates, what happens to the trade balance, other things equal?","options":["It improves, because exports become cheaper","It worsens, because the elasticities sum to less than 1","It improves, because each elasticity is positive","It is unaffected, because trade was balanced"],"answer":1,"explanation":"The Marshall–Lerner condition says depreciation improves the trade balance only if export + import elasticities exceed 1. Here 0.4 + 0.5 = 0.9 < 1, so higher import prices outweigh the volume gains.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-143","question":"A government finances its fiscal deficit by borrowing directly from the central bank (monetisation). The main macroeconomic risk is:","options":["Crowding out through higher interest rates","A fall in the money supply","An automatic current account surplus","Inflation from the increase in money supply"],"answer":3,"explanation":"Monetisation creates new reserve money, which expands money supply and can feed inflation. Market borrowing, by contrast, tends to raise interest rates.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-144","question":"The nominal exchange rate is ₹80 per dollar. A representative basket costs $100 in the US and ₹7,200 in India. What is the real exchange rate (US basket in terms of Indian baskets) and what does it imply?","options":["0.90; Indian goods are relatively expensive","1.11; Indian goods are relatively expensive","1.11; Indian goods are relatively cheap","72.00; the rupee is overvalued"],"answer":2,"explanation":"Real exchange rate = e × P* / P = 80 × 100/7,200 = 1.11. One US basket buys 1.11 Indian baskets, so Indian goods are relatively cheap, which favours Indian exports.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-145","question":"A sharp rise in global crude oil prices that raises transport and production costs across the economy is an example of:","options":["Cost-push inflation","Demand-pull inflation","Deflation","Disinflation"],"answer":0,"explanation":"Higher input costs shift aggregate supply to the left, raising prices even without extra demand — cost-push inflation.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-146","question":"Which of the following is NOT one of Porter's five competitive forces?","options":["Threat of substitute products","Bargaining power of suppliers","Government regulation","Threat of new entrants"],"answer":2,"explanation":"The five forces are rivalry among existing firms, threat of new entrants, threat of substitutes, bargaining power of buyers and bargaining power of suppliers. Regulation affects these forces but is not itself one of the five.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-147","question":"In the BCG growth–share matrix, a business with a high relative market share in a slow-growing market is a:","options":["Star","Question mark","Dog","Cash cow"],"answer":3,"explanation":"Cash cows lead mature markets, generate more cash than they need and fund other units. Stars have high share in fast-growing markets.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-148","question":"In a SWOT analysis, which elements are internal to the organisation?","options":["Opportunities and threats","Strengths and weaknesses","Strengths and opportunities","Weaknesses and threats"],"answer":1,"explanation":"Strengths and weaknesses are internal attributes the firm controls; opportunities and threats arise in the external environment.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-149","question":"A packaged-snacks company starts selling its existing product range in Middle-East markets for the first time. In the Ansoff matrix this is:","options":["Market penetration","Market development","Product development","Diversification"],"answer":1,"explanation":"Existing products in new markets (here, new geographies) = market development. New products for existing markets would be product development; new products in new markets, diversification.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-150","question":"An airline offers no free meals, a single aircraft type, online-only booking and quick turnarounds to offer the lowest fares on busy routes. Which generic strategy is it following?","options":["Cost leadership","Differentiation","Differentiation focus","Stuck in the middle"],"answer":0,"explanation":"Its activities are designed to minimise cost per seat across a broad market, the hallmark of cost leadership.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-151","question":"In Porter's value chain, which of these is a SUPPORT activity rather than a primary activity?","options":["Outbound logistics","Marketing and sales","After-sales service","Procurement"],"answer":3,"explanation":"Primary activities: inbound logistics, operations, outbound logistics, marketing and sales, service. Support activities: firm infrastructure, human resource management, technology development and procurement.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-152","question":"In the McKinsey 7S framework, which three elements are the 'hard' elements?","options":["Shared values, style and staff","Skills, staff and systems","Strategy, structure and systems","Strategy, skills and shared values"],"answer":2,"explanation":"Hard elements (strategy, structure, systems) are easier to define and change. Soft elements are shared values, style, staff and skills.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-153","question":"Laptop assemblers depend on two global suppliers of a patented chip, and redesigning around a different chip takes two years. Which force does this most strengthen, and what is the effect on assemblers' profitability?","options":["Buyer power; it raises assemblers' profitability","Threat of substitutes; it lowers suppliers' profitability","Supplier power; it lowers assemblers' profitability","Threat of entry; it raises assemblers' profitability"],"answer":2,"explanation":"Concentrated suppliers of a unique input with high switching costs for buyers have strong bargaining power and can capture much of the industry's value.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-154","question":"Which factors RAISE barriers to entry in an industry? I. Large economies of scale. II. Heavy capital requirements. III. Low customer switching costs. IV. Incumbents' control of distribution channels.","options":["I, II, III and IV","I and III only","II, III and IV","I, II and IV"],"answer":3,"explanation":"Scale economies, capital needs and controlled distribution all deter entrants. Low switching costs make it EASIER for entrants to win customers, so III lowers barriers.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-155","question":"A business unit has sales of ₹120 crore; its largest competitor has ₹300 crore. Its market is growing at 18% a year. Using the BCG matrix (relative share cut-off 1.0), how should it be classified?","options":["Question mark (relative share 0.4)","Star (relative share 2.5)","Dog (relative share 0.4)","Cash cow (relative share 2.5)"],"answer":0,"explanation":"Relative market share = own sales/largest rival's sales = 120/300 = 0.4 (< 1, low). With high market growth, the unit is a question mark. Dividing the rival's sales by the unit's gives 2.5, the common inversion error.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-156","question":"A business unit has sales of ₹400 crore against ₹250 crore for its largest rival, in a market growing at 3% a year. What does the BCG approach recommend for it?","options":["Invest heavily to build share, as it is a star","Hold share and use its surplus cash to fund stars and promising question marks","Divest it, as it is a dog","Invest selectively, as it is a question mark"],"answer":1,"explanation":"Relative share = 400/250 = 1.6 (high) and growth is low, so it is a cash cow. The standard prescription is to defend its position with minimal investment and redeploy its cash to growth businesses.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-157","question":"Rank the four Ansoff growth strategies from LOWEST to HIGHEST risk, as the framework usually presents them.","options":["Diversification, product development, market development, market penetration","Product development, market penetration, diversification, market development","Market penetration, market development or product development, diversification","Market development, diversification, market penetration, product development"],"answer":2,"explanation":"Penetration stays with known products and customers (lowest risk). Market development and product development each add one unknown. Diversification adds both, so it is the riskiest.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-158","question":"For a domestic cement company, which SWOT classification is correct?","options":["Its well-known brand — opportunity","A government push for affordable housing — strength","Its ageing kilns — threat","Rising global coal prices — threat"],"answer":3,"explanation":"Coal prices are an external, unfavourable factor (threat). A brand is an internal strength; a housing push is an external opportunity; ageing kilns are an internal weakness.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-159","question":"Assertion (A): Porter warns that a firm trying to be both the lowest-cost producer and highly differentiated across a broad market risks being 'stuck in the middle'. Reason (R): Such a firm may end up with neither the lowest costs nor a strong enough differentiation premium, leaving it below-average returns.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. Porter argued that the two strategies require different investments and cultures; trying for both usually means doing neither well (though some firms have managed both through innovation).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-160","question":"Blue Ocean Strategy's 'four actions framework' asks managers to decide which factors to:","options":["Plan, do, check and act","Eliminate, reduce, raise and create","Analyse, design, develop and evaluate","Penetrate, develop, extend and diversify"],"answer":1,"explanation":"To achieve value innovation, firms eliminate and reduce factors the industry over-serves, and raise and create factors that open uncontested market space.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-161","question":"According to Prahalad and Hamel, a core competence should satisfy which criteria?","options":["It is the firm's most profitable product line","It gives access to a wide variety of markets, contributes significantly to customer benefits and is difficult to imitate","It is protected by a patent and is owned by one division","It is based on the lowest-cost location of production"],"answer":1,"explanation":"Core competences are collective learning (for example miniaturisation) that can be leveraged across many products, matter to customers and are hard for rivals to copy.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-162","question":"Under the VRIO framework, a resource is valuable, rare and costly to imitate, but the firm is not organised to exploit it. What is the competitive implication?","options":["Sustained competitive advantage","Competitive parity","An unused (unexploited) competitive advantage","Temporary competitive advantage"],"answer":2,"explanation":"Sustained advantage requires all four: valuable, rare, inimitable and organised. Without the organisation to use it, the potential advantage remains unexploited.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-163","question":"Which combination of conditions is most likely to make rivalry among existing firms intense?","options":["High fixed costs, slow industry growth, undifferentiated products and high exit barriers","Low fixed costs, fast growth, strong brands and low exit barriers","Few competitors of very different sizes, fast growth and high switching costs","High fixed costs, fast growth, strong differentiation and low exit barriers"],"answer":0,"explanation":"High fixed costs push firms to cut price to fill capacity; slow growth makes it a fight for share; commodity products make price the main weapon; exit barriers keep weak firms in the market.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-164","question":"A car manufacturer acquires a tyre manufacturer that supplies it. This is an example of:","options":["Forward vertical integration","Horizontal integration","Conglomerate diversification","Backward vertical integration"],"answer":3,"explanation":"Moving upstream into the supply of inputs is backward integration. Buying a dealer network would be forward integration; buying another carmaker, horizontal.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-165","question":"An acquirer worth ₹500 crore buys a target worth ₹200 crore on a standalone basis by paying ₹260 crore in cash. The combined firm is valued at ₹800 crore. What is the gain to the acquirer's shareholders?","options":["₹100 crore","₹60 crore","₹40 crore","₹300 crore"],"answer":2,"explanation":"Synergy = 800 − (500 + 200) = ₹100 crore. Premium paid = 260 − 200 = ₹60 crore, which goes to the target's shareholders. Acquirer's gain = synergy − premium = ₹40 crore (check: 800 − 260 = 540, versus 500 before).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-166","question":"Why did BCG's original logic link high relative market share with higher profitability?","options":["High share always allows a firm to charge the highest prices","Regulators protect market leaders from competition","High-share firms need no investment in marketing","Higher cumulative volume moves a firm down the experience curve, lowering its unit costs"],"answer":3,"explanation":"The experience curve suggests unit costs fall by a roughly constant percentage each time cumulative output doubles, so the share leader should have the lowest costs and the highest margins.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-167","question":"Match each factor with its PESTEL category for an electric-scooter maker. (p) A new subsidy for electric vehicles, (q) Rising household disposable incomes, (r) Breakthroughs in battery chemistry, (s) Stricter battery recycling norms. Categories: (1) Political, (2) Economic, (3) Technological, (4) Environmental.","options":["p-2, q-1, r-3, s-4","p-1, q-2, r-3, s-4","p-1, q-2, r-4, s-3","p-4, q-2, r-3, s-1"],"answer":1,"explanation":"Government subsidies are political choices; incomes are economic; battery advances are technological; recycling norms address environmental impact (they could also be argued as legal, but environmental is the listed fit).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-168","question":"In Kaplan and Norton's balanced scorecard, under which perspective does 'average time taken to process a customer order' usually fall?","options":["Internal business process","Financial","Customer","Learning and growth"],"answer":0,"explanation":"Order-processing time measures how efficiently internal operations run. Customer measures look at satisfaction and retention; learning and growth covers people, skills and systems.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-169","question":"A chocolatier sells only high-priced, hand-crafted gift boxes to corporate clients in a few metro cities. Which generic strategy is this?","options":["Differentiation focus","Cost focus","Broad differentiation","Cost leadership"],"answer":0,"explanation":"It serves a narrow segment (corporate gifting in metros) with a premium, distinctive product: differentiation focus.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-170","question":"Why do digital platforms with strong network effects often see 'winner-take-most' outcomes?","options":["Their marginal cost rises sharply with each user","Regulators usually grant them exclusive licences","Users can join several rival platforms at no cost, so there is no lock-in","Each additional user makes the platform more valuable to others, so the leader's advantage feeds on itself"],"answer":3,"explanation":"With network effects, value grows with the number of users (and, for two-sided platforms, with users on the other side). This positive feedback makes it hard for smaller rivals to catch up. Easy multi-homing works against winner-take-all.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-171","question":"A group has two cash cows, one star, and three question marks, and its funds are limited. Which allocation follows BCG logic?","options":["Spread investment equally across all six units","Invest heavily in the cash cows to raise their growth rate","Use cash-cow surpluses to support the star and the most promising question mark, and divest or harvest the weaker question marks","Divest the star to fund all three question marks"],"answer":2,"explanation":"Cash cows fund growth. With limited funds, back the star to keep its leadership and pick question marks that can become stars; the rest should be harvested or sold rather than starved slowly.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-172","question":"A foreign insurer with product expertise forms a joint venture with a domestic bank that has a large branch network. The main strategic logic is:","options":["Achieving economies of scale in the same activity","Combining complementary resources: product know-how with distribution access","Reducing the number of competitors through a merger","Backward integration into raw materials"],"answer":1,"explanation":"Joint ventures often pair partners with complementary assets; here one brings products and underwriting skills, the other customers and distribution.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-173","question":"A firm's cost per unit is: inbound logistics ₹10, operations ₹30, outbound logistics ₹8, marketing ₹12 and service ₹5; it sells at ₹100. If it cuts operations cost to a rival's ₹22 and also cuts its price by 5%, what will its margin be as a percentage of the new price?","options":["43.00%","38.00%","40.00%","36.84%"],"answer":2,"explanation":"Current cost = 10 + 30 + 8 + 12 + 5 = ₹65. New cost = 65 − 8 = ₹57. New price = ₹95. Margin = 95 − 57 = ₹38 = 40.00% of the new price. 43% ignores the price cut; 38% divides by the old price.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
];

export default questions;
